// Run the live cell's rules without drawing and measure what each rule does.
const W = 960, H = 600, NEIGHBOUR_R = 60, CROWD_R = 22, MAX_SPEED = 2.6, MIN_SPEED = 1.2;
const N = Math.round(nb.get('boids_count') ?? 80);
const STEPS = 1500, EVERY = 25, SEEDS = [1986, 1987, 1988, 1989, 1990];

const settings = [
  { name: 'defaults', cohesion: 1, alignment: 1, separation: 1 },
  { name: 'alignment 0', cohesion: 1, alignment: 0, separation: 1 },
  { name: 'cohesion 2, separation 0', cohesion: 2, alignment: 1, separation: 0 },
  { name: 'separation 2, cohesion 0', cohesion: 0, alignment: 1, separation: 2 },
];

// Math.sqrt is exact everywhere; Math.hypot, sin and cos can differ between browsers,
// and a flock magnifies the tiniest difference.
const len = (x, y) => Math.sqrt(x * x + y * y);

function mulberry32(seed) {
  return () => {
    seed = (seed + 0x6D2B79F5) | 0;
    let t = Math.imul(seed ^ (seed >>> 15), 1 | seed);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

function start(seed) {
  const rand = mulberry32(seed);
  return Array.from({ length: N }, () => {
    const x = rand() * W, y = rand() * H;
    const dx = rand() - 0.5, dy = rand() - 0.5, d = len(dx, dy) || 1;   // no sin/cos: they vary too
    return { x, y, vx: dx / d * 2, vy: dy / d * 2 };
  });
}

// The same update as the live cell, boid by boid.
function step(boids, k) {
  for (const b of boids) {
    let cx = 0, cy = 0, ax = 0, ay = 0, sx = 0, sy = 0, near = 0;
    for (const o of boids) {
      if (o === b) continue;
      const dx = o.x - b.x, dy = o.y - b.y, d2 = dx * dx + dy * dy;
      if (d2 > NEIGHBOUR_R * NEIGHBOUR_R) continue;
      near++;
      cx += o.x; cy += o.y; ax += o.vx; ay += o.vy;
      if (d2 < CROWD_R * CROWD_R && d2 > 0) { const d = Math.sqrt(d2); sx -= dx / d; sy -= dy / d; }
    }
    if (near > 0) {
      b.vx += (cx / near - b.x) * 0.004 * k.cohesion;
      b.vy += (cy / near - b.y) * 0.004 * k.cohesion;
      b.vx += (ax / near - b.vx) * 0.05 * k.alignment;
      b.vy += (ay / near - b.vy) * 0.05 * k.alignment;
    }
    b.vx += sx * 0.12 * k.separation;
    b.vy += sy * 0.12 * k.separation;
    const speed = len(b.vx, b.vy) || 0.001;
    const clamped = Math.max(MIN_SPEED, Math.min(MAX_SPEED, speed));
    b.vx = b.vx / speed * clamped;
    b.vy = b.vy / speed * clamped;
    b.x = (b.x + b.vx + W) % W;
    b.y = (b.y + b.vy + H) % H;
  }
}

function order(boids) {
  let hx = 0, hy = 0;
  for (const b of boids) { const s = len(b.vx, b.vy) || 1; hx += b.vx / s; hy += b.vy / s; }
  return len(hx, hy) / boids.length;
}

function flocks(boids) {
  const parent = boids.map((_, i) => i);
  const find = i => (parent[i] === i ? i : (parent[i] = find(parent[i])));
  for (let i = 0; i < boids.length; i++) {
    for (let j = i + 1; j < boids.length; j++) {
      if (len(boids[i].x - boids[j].x, boids[i].y - boids[j].y) <= NEIGHBOUR_R) {
        parent[find(i)] = find(j);
      }
    }
  }
  return new Set(boids.map((_, i) => find(i))).size;
}

function nearest(boids) {
  let total = 0;
  for (const b of boids) {
    let best = Infinity;
    for (const o of boids) if (o !== b) best = Math.min(best, len(o.x - b.x, o.y - b.y));
    total += best;
  }
  return total / boids.length;
}

const rows = [];
console.log(N + ' boids, ' + STEPS + ' steps, average of ' + SEEDS.length + ' starts\n');
console.log('setting                    order  flocks  nearest neighbour');
for (const k of settings) {
  const sums = new Array(STEPS / EVERY + 1).fill(0);
  let flockTotal = 0, nearestTotal = 0;
  for (const seed of SEEDS) {
    const boids = start(seed);
    for (let t = 0; t <= STEPS; t++) {
      if (t % EVERY === 0) sums[t / EVERY] += order(boids);
      if (t < STEPS) step(boids, k);
    }
    flockTotal += flocks(boids);
    nearestTotal += nearest(boids);
  }
  sums.forEach((sum, i) => rows.push({ step: i * EVERY, order: +(sum / SEEDS.length).toFixed(3), setting: k.name }));
  console.log(k.name.padEnd(26) + (sums.at(-1) / SEEDS.length).toFixed(2).padStart(6) +
    (flockTotal / SEEDS.length).toFixed(1).padStart(8) +
    ((nearestTotal / SEEDS.length).toFixed(1) + ' px').padStart(19));
}

return {
  $schema: 'https://vega.github.io/schema/vega-lite/v5.json',
  width: 'container',
  height: 280,
  title: 'Order: how well the headings agree (average of 5 starts)',
  data: { values: rows },
  mark: { type: 'line', strokeWidth: 2 },
  encoding: {
    x: { field: 'step', type: 'quantitative' },
    y: { field: 'order', type: 'quantitative', scale: { domain: [0, 1] }, title: 'order (1 = all the same way)' },
    color: { field: 'setting', type: 'nominal', title: null, sort: settings.map(s => s.name) },
  },
};
